<section>
    <div class="section-heading"><div><p class="eyebrow"><?= App\Core\View::e($phase['name']) ?></p><h1>Grupos</h1><p>Distribuicao, retirada e movimentação bloqueiam apos inicio.</p></div><a class="button" href="<?= App\Core\View::e(App\Core\Config::url('/admin/fases?championship_id=' . $phase['championship_id'])) ?>">Voltar para fases</a></div>
    <?php if (!empty($message)): ?><p class="success" role="status"><?= App\Core\View::e($message) ?></p><?php endif; ?>
    <?php if ($canManage): ?><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= App\Core\View::e(App\Core\Security::csrfToken()) ?>"><input type="hidden" name="phase_id" value="<?= (int) $phase['id'] ?>"><label>Nome <input name="name" required placeholder="Grupo A"></label><label>Codigo <input name="code" required placeholder="A"></label><label>Ordem <input type="number" name="display_order" value="1" min="1"></label><button type="submit">Criar grupo</button></form><?php endif; ?>
    <?php foreach ($groups as $group): ?><article class="panel"><header><h2><?= App\Core\View::e($group['name']) ?></h2><span class="status status-<?= App\Core\View::e($group['status']) ?>"><?= (int) $group['active_teams_count'] ?>/<?= (int) $group['teams_limit'] ?> equipes</span></header><?php if ($canManage): ?><form method="post" action="<?= App\Core\View::e(App\Core\Config::url('/admin/grupos/' . $group['id'])) ?>" class="form-grid"><input type="hidden" name="_csrf" value="<?= App\Core\View::e(App\Core\Security::csrfToken()) ?>"><label>Nome <input name="name" value="<?= App\Core\View::e($group['name']) ?>" required></label><label>Codigo <input name="code" value="<?= App\Core\View::e($group['code']) ?>" required></label><label>Limite <input type="number" name="teams_limit" min="1" value="<?= (int) $group['teams_limit'] ?>"></label><label>Classificados <input type="number" name="qualified_limit" min="1" value="<?= (int) $group['qualified_limit'] ?>"></label><button type="submit">Salvar grupo</button></form><?php endif; ?><ul><?php foreach (($groupTeams[(int) $group['id']] ?? []) as $member): ?><li><?= App\Core\View::e($member['team_name']) ?><?php if ($canManage && $member['status'] === 'active'): ?> <form method="post" class="inline-form" action="<?= App\Core\View::e(App\Core\Config::url('/admin/grupos/' . $group['id'] . '/equipes/' . $member['team_id'] . '/remover')) ?>"><input type="hidden" name="_csrf" value="<?= App\Core\View::e(App\Core\Security::csrfToken()) ?>"><button type="submit">Retirar</button></form><?php endif; ?></li><?php endforeach; ?></ul><?php if ($canManage && in_array($group['status'], ['draft', 'published'], true)): ?><form method="post" action="<?= App\Core\View::e(App\Core\Config::url('/admin/grupos/' . $group['id'] . '/equipes')) ?>" class="form-grid"><input type="hidden" name="_csrf" value="<?= App\Core\View::e(App\Core\Security::csrfToken()) ?>"><label>Adicionar equipe <select name="team_id" required><option value="">Selecione</option><?php foreach ($teams as $team): ?><option value="<?= (int) $team['id'] ?>"><?= App\Core\View::e($team['name']) ?></option><?php endforeach; ?></select></label><label>Posição <input type="number" min="1" name="position"></label><button type="submit">Distribuir</button></form><?php endif; ?></article><?php endforeach; ?>
</section>
